from collections import deque

def solve():
    n = int(input())
    board = []
    for _ in range(n):
        board.append(input().strip())

    # Find starting positions
    pos_a = pos_b = None
    for i in range(n):
        for j in range(n):
            if board[i][j] == 'A':
                pos_a = (i, j)
            elif board[i][j] == 'B':
                pos_b = (i, j)

    # BFS with game theory
    # State: (ax, ay, bx, by, turn) - turn: 0=A, 1=B
    visited = set()
    queue = deque([(pos_a[0], pos_a[1], pos_b[0], pos_b[1], 0)])
    visited.add((pos_a[0], pos_a[1], pos_b[0], pos_b[1], 0))

    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    while queue:
        ax, ay, bx, by, turn = queue.popleft()

        if turn == 0:  # A's turn
            if (ax, ay) == pos_b:
                return 'A'
            for dx, dy in directions:
                nx, ny = ax + dx, ay + dy
                if 0 <= nx < n and 0 <= ny < n and board[nx][ny] != '#':
                    state = (nx, ny, bx, by, 1)
                    if state not in visited:
                        visited.add(state)
                        queue.append(state)
        else:  # B's turn
            if (bx, by) == pos_a:
                return 'B'
            for dx, dy in directions:
                nx, ny = bx + dx, by + dy
                if 0 <= nx < n and 0 <= ny < n and board[nx][ny] != '#':
                    state = (ax, ay, nx, ny, 0)
                    if state not in visited:
                        visited.add(state)
                        queue.append(state)

    return 'B'

