            diag++;
            sumDiag += diag;
        }

        int pos = x - (sumDiag - diag);

        int numerator, denominator;

        if (diag % 2 == 0) {
            numerator = pos;
            denominator = diag - pos + 1;
        } else {
            numerator = diag - pos + 1;
            denominator = pos;
        }

        System.out.println(numerator + "/" + denominator);
    }
