import java.util.*;
import java.io.*;

public class Main {
    static class State {
        int r, c, keys, dist;
        State(int r, int c, int keys, int dist) {
            this.r = r;
            this.c = c;
            this.keys = keys;
            this.dist = dist;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] board = new char[n][m];
        int sr = 0, sc = 0;

        for (int i = 0; i < n; i++) {
            board[i] = br.readLine().toCharArray();
            for (int j = 0; j < m; j++) {
                if (board[i][j] == '0') {
                    sr = i;
                    sc = j;
                }
            }
        }

        Queue<State> queue = new LinkedList<>();
        boolean[][][] visited = new boolean[n][m][64];

        queue.add(new State(sr, sc, 0, 0));
        visited[sr][sc][0] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            if (board[cur.r][cur.c] == '1') {
                System.out.println(cur.dist);
                return;
            }

            for (int i = 0; i < 4; i++) {
                int nr = cur.r + dr[i];
                int nc = cur.c + dc[i];

                if (nr < 0 || nr >= n || nc < 0 || nc >= m || board[nr][nc] == '#')
                    continue;

                int newKeys = cur.keys;
                char cell = board[nr][nc];

                if (cell >= 'a' && cell <= 'f') {
                    newKeys |= (1 << (cell - 'a'));
                }

                if (cell >= 'A' && cell <= 'F') {
                    if ((cur.keys & (1 << (cell - 'A'))) == 0)
                        continue;
                }

                if (!visited[nr][nc][newKeys]) {
                    visited[nr][nc][newKeys] = true;
                    queue.add(new State(nr, nc, newKeys, cur.dist + 1));
                }
            }
        }

        System.out.println(-1);
    }
}

