int parent[10001];
int rankArr[10001];

int find(int x) {
    if (parent[x] != x) {
        parent[x] = find(parent[x]);
    }
    return parent[x];
}

bool unionSets(int x, int y) {
    int px = find(x);
    int py = find(y);

    if (px == py) return false;

    if (rankArr[px] < rankArr[py]) {
        parent[px] = py;
    } else if (rankArr[px] > rankArr[py]) {
        parent[py] = px;
    } else {
        parent[py] = px;
        rankArr[px]++;
    }

    return true;
}

