import java.util.*;
import java.io.*;

public class Main {
    static List<Integer>[] graph;
    static List<Integer> circuit = new ArrayList<>();

    static void dfs(int u) {
        while (!graph[u].isEmpty()) {
            int v = graph[u].remove(graph[u].size() - 1);
            if (!graph[v].isEmpty()) {
                graph[v].remove((Integer)u);
            }
            dfs(v);
        }
        circuit.add(u);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());

        graph = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }

        int edgeCount = 0;

        for (int i = 1; i <= n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int j = 1; j <= n; j++) {
                int cnt = Integer.parseInt(st.nextToken());
                if (i < j && cnt > 0) {
                    for (int k = 0; k < cnt; k++) {
                        graph[i].add(j);
                        graph[j].add(i);
                        edgeCount++;
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            if (graph[i].size() % 2 != 0) {
                System.out.println(-1);
                return;
            }
        }

        int start = 1;
        for (int i = 1; i <= n; i++) {
            if (!graph[i].isEmpty()) {
                start = i;
                break;
            }
        }

        dfs(start);

        if (circuit.size() != edgeCount + 1) {
            System.out.println(-1);
        } else {
            Collections.reverse(circuit);
            for (int i = 0; i < circuit.size(); i++) {
                System.out.print(circuit.get(i));
                if (i < circuit.size() - 1) System.out.print(" ");
            }
            System.out.println();
        }
    }
}

