void dfs(int u) {
    while (!graph[u].empty()) {
        int v = graph[u].back();
        graph[u].pop_back();

        auto it = find(graph[v].begin(), graph[v].end(), u);
        if (it != graph[v].end()) {
            graph[v].erase(it);
        }

        dfs(v);
    }
    circuit.push_back(u);
}

